<?php
require __DIR__.'/client_profiles.php';
require APPPATH.'services/NativeCompanyClients.php';
require APPPATH.'services/CompanyCustomerGroupsSchema.php';
$id=$db->driver()==='sqlite'?'INTEGER PRIMARY KEY AUTOINCREMENT':'INT NOT NULL AUTO_INCREMENT PRIMARY KEY';
$db->query("CREATE TABLE {$p}customers_groups(id $id,name varchar(191) NOT NULL)");
$db->query("CREATE TABLE {$p}customer_groups(id $id,customer_id int NOT NULL,groupid int NOT NULL)");
if($db->driver()==='sqlite')$db->query("CREATE TABLE {$p}company_customer_group_owners(group_id int NOT NULL PRIMARY KEY,issuer_id int NOT NULL,FOREIGN KEY(group_id) REFERENCES {$p}customers_groups(id),FOREIGN KEY(issuer_id) REFERENCES {$p}issuers_registry(id))");
else CompanyCustomerGroupsSchema::ensure($db,$p);
unset($db->data_cache['table_names']);
foreach(CompanyClientNativeFields::TEXT as $field=>$max)$db->query('ALTER TABLE '.$p.'clients ADD '.$field.' varchar('.$max.') DEFAULT NULL');
foreach(CompanyClientNativeFields::IDS as $field)if($field!=='country')$db->query('ALTER TABLE '.$p.'clients ADD '.$field.' int NOT NULL DEFAULT 0');
$db->query('ALTER TABLE '.$p.'clients ADD registration_confirmed int NOT NULL DEFAULT 1');
$db->query('ALTER TABLE '.$p.'clients ADD leadid int DEFAULT NULL');
$db->query('CREATE TABLE '.$p.'currencies(id int PRIMARY KEY,name varchar(10),symbol varchar(10),isdefault int)');
$db->query("INSERT INTO {$p}currencies VALUES(1,'BRL','R$',1)");
$db->query('ALTER TABLE '.$p.'countries ADD short_name varchar(100)');
$db->query("UPDATE {$p}countries SET short_name='Brazil'");
if(!$db->table_exists($p.'contacts'))$db->query('CREATE TABLE '.$p.'contacts(id int PRIMARY KEY,userid int,active int,is_primary int,last_login datetime)');
foreach(['firstname','lastname','email']as$field)if(!$db->field_exists($field,$p.'contacts'))$db->query('ALTER TABLE '.$p.'contacts ADD '.$field.' varchar(191)');
require_once APPPATH.'services/NativeCompanyCustomFields.php';NativeCompanyCustomFieldSchema::ensure($db,$p);
$adapterA=new NativeCompanyClients($db,$p,41,12);$adapterB=new NativeCompanyClients($db,$p,82,12);
$payload=['native_customer_fields_revision'=>hash('sha256','[]'),'company'=>'Native company A','vat'=>'','request_key'=>hash('sha256','native-client-request'), 'website'=>'https://example.test/a','billing_street'=>'A billing','shipping_city'=>'A shipping','country'=>'32','default_currency'=>'1','default_language'=>'portuguese','address'=>'A street'];
$nativeA=$adapterA->save($payload);$nativeB=$adapterB->save(array_replace($payload,['company'=>'Native company B','request_key'=>hash('sha256','native-client-request-b'),'website'=>'https://example.test/b']));
essentialCheck($nativeA!==$nativeB,'native form creates distinct owned customers');
$detail=$adapterA->details($nativeA);essentialCheck($detail['native_profile']['website']==='https://example.test/a'&&$detail['native_profile']['billing_street']==='A billing','native website/billing persisted under owner');
essentialCheck($adapterA->save($payload)===$nativeA,'complete native form replay does not duplicate');
$changed=array_replace($payload,['website'=>'https://example.test/replay-change']);essentialThrows(fn()=>$adapterA->save($changed),'company_client_request_conflict','create receipt binds additional native fields');
$edit=array_replace($payload,['company'=>'Native A edited','revision'=>$detail['revision'],'shipping_city'=>'A changed']);
$adapterA->save($edit,$nativeA);essentialThrows(fn()=>$adapterA->save($edit,$nativeA),'company_client_stale','native shipping revision participates in stale check');
essentialThrows(fn()=>$adapterB->billing($nativeA),'company_client_access_denied','native billing endpoint refuses foreign owner');
essentialCheck($adapterA->billing($nativeA)[0]['billing_street']==='A billing','native billing endpoint preserves original list response');
essentialCheck($adapterB->details($nativeA)===null,'B cannot read unshared A customer');
essentialThrows(fn()=>$adapterB->save($edit,$nativeA),'company_client_access_denied','B cannot write A customer');
$detail=$adapterA->details($nativeA);$clients->setSharing(41,12,$nativeA,[82],$detail['revision']);
$shared=$adapterB->details($nativeA);essentialCheck($shared['profile']===[]&&!isset($shared['native_profile']),'shared identity contains no native private form values');
foreach(['owner_issuer_id'=>82,'stripe_id'=>'not-a-real-token','active'=>'0'] as $key=>$value)essentialThrows(fn()=>$adapterA->save($payload+[$key=>$value]),'company_client_invalid_input','native form rejects overpost '.$key);
essentialThrows(fn()=>CompanyClientNativeFields::normalize(['website'=>'javascript:alert(1)']),'company_client_invalid_input','non-HTTP website rejected');
essentialThrows(fn()=>CompanyClientNativeFields::normalize(['country'=>'1 OR 1=1']),'company_client_invalid_input','reference IDs must be canonical integers');
$before=$adapterA->details($nativeA);$db->failOn='INSERT INTO '.$p.'issuers_audit';
essentialThrows(fn()=>$adapterA->save(array_replace($payload,['revision'=>$before['revision'],'website'=>'https://example.test/rollback']),$nativeA),'issuer_storage_failed','native field save rolls back on audit failure');$db->failOn=null;
essentialCheck($adapterA->details($nativeA)===$before,'native row/profile/revision restored after failed audit');
$page=$adapterB->table(['draw'=>'2','start'=>'0','length'=>'100','search'=>['value'=>'Native'],'order'=>[['column'=>'2','dir'=>'asc']]]);
$sharedRow=array_values(array_filter($page['rows'],fn($r)=>(int)$r['userid']===$nativeA))[0];
essentialCheck($sharedRow['phonenumber']===null&&$sharedRow['datecreated']===null,'native table never discloses shared private fields');
essentialCheck(count($page['rows'])===2&&$page['draw']===2,'native DataTable protocol returns owned and explicitly shared identities');
essentialThrows(fn()=>NativeCompanyClients::request(['length'=>'-1']),'company_client_invalid_page','unbounded native DataTable exports refused');
essentialThrows(fn()=>NativeCompanyClients::request(['order'=>[['column'=>2,'dir'=>'asc; DROP TABLE x']]]),'company_client_invalid_page','native table ordering is allowlisted');
$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=82 AND staff_id=12 AND feature='customers' AND capability='view'");
essentialThrows(fn()=>$adapterB->table([]),'company_client_access_denied','revoked customer ACL rejects native table');
echo "Native customers adapter tests passed.\n";

$db->query('UPDATE '.$p.'clients SET registration_confirmed=0,leadid=91 WHERE userid=?',[$nativeA]);
$readOnly=$adapterA->details($nativeA)['native_profile'];essentialCheck((int)$readOnly['registration_confirmed']===0&&(int)$readOnly['leadid']===91,'native renderer receives actual registration and lead provenance, not invented defaults');
essentialThrows(fn()=>CompanyClientNativeFields::normalize(['registration_confirmed'=>'1']),'company_client_invalid_input','ordinary profile cannot self-approve registration');
